    if(rval==-1)    
    {
        perror("BIND-ERR:");
        close(sid);
        exit(1);
    }
    rval=listen(sid,5);
    if(rval==-1)
    {
        perror("LISTEN-ERR:");
        close(sid);
        exit(1);
    }
    clen=sizeof(c);
    sid1=accept(sid,(struct sockaddr*)&c,&clen);
    rval=recv(sid1,buffer,sizeof(buffer),0);
    if(rval==-1)
    {
        perror("MSG-RCV-ERR:");
    }
    else
    {
        printf("\nClient request is %s\n",buffer);
    }
