{
    listint_t *current;
    listint_t *sorted;
    if (list == NULL || *list == NULL || (*list)->next == NULL)
        return;
    sorted = *list;
    current = (*list)->next;
    while (current != NULL)
    {
        if (sorted != NULL &&  current->n < sorted->n)
        {
            current = swap(&current, &sorted);
            sorted = current->prev;
            if (sorted == NULL)
                *list = current;
            print_list(*list);
            while (sorted != NULL && current->n < sorted->n)
            {
                current = swap(&current, &sorted);
                sorted = current->prev;
                if (sorted == NULL)
                    *list = current;
                print_list(*list);
            }
        }
        else
        {
            sorted = current;
            current = sorted->next;
        }
    }
}

