void rem_file(char name)
{
    if(isthere(name)==-1)
        printf("\nFile does not exist");
    else
    {
        temp=start;
        q=temp;
        while(temp->next!=NULL)
        {
            if(temp->file==name)
            {
                if(temp==start)
                {
                    start=start->next;
                    free(temp);
                    temp=start;
                }
                else
                {
                    q->next=temp->next;
                    free(temp);
                    temp=q->next;
                }
            }
            q=temp;
            temp=temp->next;
        }
        if(temp->file==name)
        {
            q->next=NULL;
            free(temp);
        }
    }
}

