node* deletion(node* root, int n)
{
    if (root==NULL) return root;
    if (n<root->data)
        root->left=deletion(root->left,n);
    else if (n>root->data)
        root->right=deletion(root->right,n);
    else
    {
        if(root->left==NULL)
        {
            node* temp=root->right;
            free(root);
            return temp;
        }
        else if(root->right==NULL)
        {
            node* temp=root->left;
            free(root);
            return temp;
        }
        node* temp=root->right;
        while (temp&&temp->left!=NULL)
            temp=temp->left;
        root->data=temp->data;
