int     check_bishop(char **tab, int row, int col, int size)
{
    int     r;
    int     c;
    r = row - 1;
    c = col - 1;
    while (r >= 0 && c >= 0 && !is_piece(tab[r][c]))
        if (tab[r--][c--] == 'K')
            return (1);
    r = row - 1;
    c = col + 1;
    while (r >= 0 && c < size && !is_piece(tab[r][c]))
        if (tab[r--][c++] == 'K')
            return (1);
    r = row + 1;
    c = col - 1;
    while (r < size && c >= 0 && !is_piece(tab[r][c]))
        if (tab[r++][c--] == 'K')
            return (1);
    r = row + 1;
    c = col + 1;
    while (r < size && c < size && !is_piece(tab[r][c]))
        if (tab[r++][c++] == 'K')
            return (1);
    return (0);
}

