   {
      ret = Semaphore_pend(semaphore->handle, BIOS_NO_WAIT);
   }
   else if(timeout == INFINITE_DELAY)
   {
      ret = Semaphore_pend(semaphore->handle, BIOS_WAIT_FOREVER);
