}

size_t count_leaves(const binary_tree_t *tree, size_t leaves)
{
    size_t left;
    size_t right;
    left = leaves;
    right = leaves;
    if (tree == NULL)
    {
        return (0);
    }
    if (tree->left == NULL && tree->right == NULL)
    {
        return (1);
    }
    left = count_leaves(tree->left, leaves);
    right = count_leaves(tree->right, leaves);
    return (left + right);
}

