void freeexpression(TERM* e) {
    if(e->type == arrayitem)
        freearray(e->array);
    else if(e->type == innerexpression || e->type == unaryopterm)
        freeexpression(e->expression);
    else if(e->type == subroutcall)
        freesubroutcall(e->call);
    TERM* next = e->next;
    free(e);
    if(next != NULL)
        freeexpression(next);
}

