node* pop(node* head)
{
    if(head==NULL)
        printf("CAN'T POP, STACK EMPTY\n");
    else if(head->next==NULL)
    {
        printf("%d popped from stack\n",head->data);
        free(head);
        return NULL;
    }
    else
    {
        head->next=pop(head->next);
        return head;
    }
}

