int min(int i, int j, float **A, float *p) {
    int index;
    float min = 999;
    for(int k = i; k <= j; k++) {
        if(A[i][k-1] + A[k+1][j] + sum(i, j, p) < min) {
            min = A[i][k-1] + A[k+1][j] + sum(i, j, p);
            index = k;
        }
    }
    return index;
}

